{{ config(
            materialized='table',
                post_hook={
                    "sql": "DROP TABLE IF EXISTS public.tuco_kids_RETURNS_CONSOLIDATED; CREATE TABLE public.tuco_kids_RETURNS_CONSOLIDATED ( return_date DATE, marketing_channel VARCHAR(256), marketplace VARCHAR(256), total_return_amount NUMERIC(15,2), total_return_amount_excl_tax NUMERIC(15,2), total_returned_quantity NUMERIC(15,2) ); CREATE TABLE IF NOT EXISTS public.tuco_kids_ga_sessions_consolidated ( shop_name VARCHAR(65535), channel VARCHAR(65535), date DATE, sessions NUMERIC(18) ); DROP TABLE IF EXISTS public.tuco_kids_Sales_Cost_Source; CREATE TABLE public.tuco_kids_Sales_Cost_Source AS WITH Sessions AS ( SELECT date, channel AS marketing_channel, CASE WHEN LOWER(shop_name) LIKE \'%website%\' THEN \'WEBSITE\' ELSE UPPER(SHOP_NAME) END AS marketplace, SUM(sessions) AS Sessions FROM public.tuco_kids_ga_sessions_consolidated GROUP BY 1, 2, 3 UNION ALL Select cast(DATAENDTIME as date) Date, \'AMAZON\' as marketing_channel, \'AMAZON\' as marketplace, SUM(COALESCE(CAST(JSON_EXTRACT_PATH_TEXT(trafficbyasin::INT, \'sessions\') AS INT),0)) AS sessions From public.Amazon_Tuco_Kids_GET_SALES_AND_TRAFFIC_REPORT_ASIN group by 1,2,3 ), returnsales AS ( SELECT CAST(return_date AS DATE) AS return_date, marketing_channel, CASE WHEN LOWER(marketplace) LIKE \'%amazon%\' THEN \'AMAZON\' WHEN LOWER(marketplace) LIKE \'%shopify%\' THEN \'WEBSITE\' ELSE UPPER(marketplace) END AS marketplace, SUM(total_return_amount) AS TOTAL_RETURN_AMOUNT, SUM(total_return_amount_excl_tax) AS TOTAL_RETURN_AMOUNT_EXCL_TAX, SUM(total_returned_quantity) AS TOTAL_RETURNED_QUANTITY FROM public.tuco_kids_RETURNS_CONSOLIDATED GROUP BY 1, 2, 3 ORDER BY 1 DESC ), orders AS ( SELECT CAST(FI.order_date AS DATE) AS Date, UPPER(marketplace) AS Marketplace, UPPER(FI.CHANNEL) AS marketing_CHANNEL, SUM(COALESCE(FI.GROSS_SALES_BEFORE_TAX, 0)) - SUM(COALESCE(FI.discount, 0)) - (SUM(COALESCE(FI.shopify_refund_value, 0)) - SUM(COALESCE(FI.return_tax, 0))) + (SUM(COALESCE(tax, 0)) - SUM(COALESCE(FI.return_tax, 0))) AS Total_Sales, (SUM(COALESCE(FI.shopify_refund_value, 0)) - SUM(COALESCE(FI.return_tax, 0))) AS TOTAL_SHOPIFY_REFUND_VALUE, SUM(COALESCE(GROSS_SALES_BEFORE_TAX, 0)) AS Total_Value_Before_Discount, SUM(COALESCE(FI.GROSS_SALES_BEFORE_TAX, 0)) - SUM(COALESCE(FI.discount, 0)) - (SUM(COALESCE(FI.shopify_refund_value, 0)) - SUM(COALESCE(FI.return_tax, 0))) + (SUM(COALESCE(tax, 0)) - SUM(COALESCE(FI.return_tax, 0))) - COALESCE(SUM(CASE WHEN LOWER(COALESCE(ORDER_STATUS, \'\')) LIKE \'%cancel%\' OR LOWER(COALESCE(FINAL_SHIPPING_STATUS, \'\')) LIKE \'%cancel%\' THEN COALESCE(FI.GROSS_SALES_BEFORE_TAX, 0) - COALESCE(FI.discount, 0) - (COALESCE(FI.shopify_refund_value, 0) - COALESCE(FI.return_tax, 0)) + (COALESCE(tax, 0) - COALESCE(FI.return_tax, 0)) ELSE 0 END), 0) AS TOTAL_SALES_EXCL_CANCL, COUNT(DISTINCT FI.order_id) AS Total_Orders, COUNT(DISTINCT FI.order_id) - COUNT(DISTINCT CASE WHEN LOWER(FI.order_status) IN (\'cancelled\') THEN FI.order_id END) AS Orders_EXCL_CANCL, COUNT(DISTINCT (CASE WHEN LOWER(FI.new_customer_flag) = \'new\' THEN FI.order_id END)) AS New_Customer_Orders, COUNT(DISTINCT (CASE WHEN LOWER(FI.new_customer_flag) = \'new\' THEN FI.order_id END)) - COUNT(DISTINCT (CASE WHEN LOWER(FI.new_customer_flag) = \'new\' AND LOWER(FI.order_status) IN (\'cancelled\') THEN FI.order_id END)) AS New_Customer_Orders_EXCL_CANCL, COUNT(DISTINCT (CASE WHEN LOWER(FI.new_customer_flag) = \'new\' THEN FI.customer_id_final END)) AS Total_New_Customers, COUNT(DISTINCT (CASE WHEN LOWER(FI.new_customer_flag) = \'new\' THEN FI.customer_id_final END)) - COUNT(DISTINCT (CASE WHEN LOWER(FI.new_customer_flag) = \'new\' AND LOWER(FI.order_status) IN (\'cancelled\') AND FI.return_flag = 0 THEN FI.customer_id_final END)) AS New_Customers_EXCL_CANCL, COUNT(DISTINCT FI.customer_id_final) AS TOTAL_Unique_Customers, (COUNT(DISTINCT FI.customer_id_final) - COUNT(DISTINCT CASE WHEN LOWER(FI.order_status) IN (\'cancelled\') THEN FI.customer_id_final END)) AS Unique_Customers_EXCL_CANCL, COUNT(DISTINCT (CASE WHEN LOWER(FI.new_customer_flag) = \'repeat\' THEN FI.customer_id_final END)) AS Repeat_Customers, (COUNT(DISTINCT (CASE WHEN LOWER(FI.new_customer_flag) = \'repeat\' THEN FI.customer_id_final END)) - COUNT(DISTINCT (CASE WHEN LOWER(FI.new_customer_flag) = \'repeat\' AND LOWER(FI.order_status) IN (\'cancelled\') AND FI.return_flag = 0 THEN FI.customer_id_final END))) AS Repeat_Customers_EXCL_CANCL, COALESCE(SUM(FI.discount), 0) AS TOTAL_DISCOUNT, (COALESCE(SUM(FI.discount), 0) - COALESCE(SUM(CASE WHEN LOWER(FI.order_status) IN (\'cancelled\') THEN FI.discount END), 0)) AS TOTAL_DISCOUNT_EXCL_CANCL, COALESCE(SUM(FI.tax), 0) AS TOTAL_TAX, (COALESCE(SUM(FI.tax), 0) - COALESCE(SUM(CASE WHEN LOWER(FI.order_status) IN (\'cancelled\') THEN FI.tax END), 0)) AS TAX_EXCL_CANCL, COALESCE(SUM(FI.shipping_price), 0) AS TOTAL_SHIPPING_PRICE, (COALESCE(SUM(FI.shipping_price), 0) - COALESCE(SUM(CASE WHEN LOWER(FI.order_status) IN (\'cancelled\') THEN FI.shipping_price END), 0)) AS SHIPPING_PRICE_EXCL_CANCL, COALESCE(SUM(CASE WHEN LOWER(FI.new_customer_flag) = \'new\' THEN FI.discount END), 0) AS New_Customer_Discount, (COALESCE(SUM(CASE WHEN LOWER(FI.new_customer_flag) = \'new\' THEN FI.discount END), 0) - COALESCE(SUM(CASE WHEN LOWER(FI.new_customer_flag) = \'new\' AND LOWER(order_status) IN (\'cancelled\') THEN FI.discount END), 0)) AS New_Customer_Discount_EXCL_CANCL, COALESCE(SUM(FI.quantity), 0) AS TOTAL_QUANTITY, (COALESCE(SUM(FI.quantity), 0) - COALESCE(SUM(CASE WHEN LOWER(FI.order_status) IN (\'cancelled\') THEN FI.quantity END), 0)) AS QUANTITY_EXCL_CANCL, COALESCE(SUM(CASE WHEN FI.return_flag = 1 THEN FI.quantity END), 0) AS Return_Quantity, COALESCE(SUM(CASE WHEN FI.return_flag = 1 THEN COALESCE(FI.GROSS_SALES_BEFORE_TAX, 0) - COALESCE(FI.discount, 0) - (COALESCE(FI.shopify_refund_value, 0) - COALESCE(FI.return_tax, 0)) + (COALESCE(tax, 0) - COALESCE(FI.return_tax, 0)) END), 0) AS Return_Value, COUNT(DISTINCT CASE WHEN LOWER(order_status) IN (\'cancelled\') THEN order_id END) AS Cancelled_Orders, COUNT(DISTINCT CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') AND return_flag = 0 THEN order_id END) AS Net_Orders, COUNT(DISTINCT CASE WHEN LOWER(order_status) IN (\'delivered\') THEN order_id END) AS Delivered_Orders, COUNT(DISTINCT CASE WHEN LOWER(order_status) IN (\'returned\', \'rto\') THEN order_id END) AS Returned_Orders, COUNT(DISTINCT CASE WHEN dispatch_date IS NOT NULL AND LOWER(order_status) NOT IN (\'cancelled\') THEN order_id END) AS Dispatched_Orders, COUNT(DISTINCT CASE WHEN LOWER(order_status) IN (\'shipped\', \'printed\', \'confirmed\', \'returned\', \'ready to dispatch\') THEN order_id END) AS Realised_Orders, COALESCE(SUM(CASE WHEN LOWER(order_status) IN (\'delivered\') THEN (COALESCE(FI.GROSS_SALES_BEFORE_TAX, 0) - COALESCE(FI.discount, 0) - (COALESCE(FI.shopify_refund_value, 0) - COALESCE(FI.return_tax, 0)) + (COALESCE(tax, 0) - COALESCE(FI.return_tax, 0)) - COALESCE(FI.TAX, 0)) END), 0) AS Delivered_Revenue, COALESCE(SUM(CASE WHEN LOWER(order_status) IN (\'returned\', \'rto\') THEN (COALESCE(FI.GROSS_SALES_BEFORE_TAX, 0) - COALESCE(FI.discount, 0) - (COALESCE(FI.shopify_refund_value, 0) - COALESCE(FI.return_tax, 0)) + (COALESCE(tax, 0) - COALESCE(FI.return_tax, 0)) - COALESCE(FI.TAX, 0)) END), 0) AS Returned_Revenue, COALESCE(SUM(CASE WHEN dispatch_date IS NOT NULL AND LOWER(order_status) NOT IN (\'cancelled\') THEN (COALESCE(FI.GROSS_SALES_BEFORE_TAX, 0) - COALESCE(FI.discount, 0) - (COALESCE(FI.shopify_refund_value, 0) - COALESCE(FI.return_tax, 0)) + (COALESCE(tax, 0) - COALESCE(FI.return_tax, 0))) ELSE 0 END), 0) AS Dispatched_Revenue, COALESCE(SUM(CASE WHEN LOWER(order_status) IN (\'shipped\', \'printed\', \'confirmed\', \'returned\', \'ready to dispatch\') THEN (COALESCE(FI.GROSS_SALES_BEFORE_TAX, 0) - COALESCE(FI.discount, 0) - (COALESCE(FI.shopify_refund_value, 0) - COALESCE(FI.return_tax, 0)) + (COALESCE(tax, 0) - COALESCE(FI.return_tax, 0))) ELSE 0 END), 0) AS Realised_Revenue, COUNT(CASE WHEN DATE_TRUNC(\'month\', acquisition_date) >= DATEADD(month, -3, DATE_TRUNC(\'month\', order_date)) AND DATE_TRUNC(\'month\', acquisition_date) < DATE_TRUNC(\'month\', order_date) THEN customer_id_final END) AS L3M_Customers_Retained, COUNT(CASE WHEN DATE_TRUNC(\'month\', acquisition_date) >= DATEADD(month, -6, DATE_TRUNC(\'month\', order_date)) AND DATE_TRUNC(\'month\', acquisition_date) < DATE_TRUNC(\'month\', order_date) THEN customer_id_final END) AS L6M_Customers_Retained, COUNT(CASE WHEN DATE_TRUNC(\'month\', acquisition_date) >= DATEADD(month, -12, DATE_TRUNC(\'month\', order_date)) AND DATE_TRUNC(\'month\', acquisition_date) < DATE_TRUNC(\'month\', order_date) THEN customer_id_final END) AS L12M_Customers_Retained, SUM(CASE WHEN LOWER(FI.new_customer_flag) = \'repeat\' THEN (COALESCE(FI.GROSS_SALES_BEFORE_TAX, 0) - COALESCE(FI.discount, 0) - (COALESCE(FI.shopify_refund_value, 0) - COALESCE(FI.return_tax, 0)) + (COALESCE(tax, 0) - COALESCE(FI.return_tax, 0))) ELSE 0 END) AS Repeat_Customer_Revenue, COUNT(DISTINCT CASE WHEN LOWER(FI.payment_mode) IN (\'cod\') THEN FI.order_id END) AS COD_Orders FROM public.tuco_kids_SALES_CONSOLIDATED_FINAL FI GROUP BY 1, 2, 3 ), spendd2c AS ( SELECT date, CASE WHEN (LOWER(channel) LIKE \'%facebook%\' OR LOWER(channel) LIKE \'%google%\') THEN \'WEBSITE\' WHEN LOWER(channel) LIKE \'%amazon%\' THEN \'AMAZON\' WHEN LOWER(channel) LIKE \'%flipkart%\' THEN \'FLIPKART\' WHEN LOWER(channel) LIKE \'%myntra%\' THEN \'MYNTRA\' ELSE UPPER(channel) END AS Marketplace, UPPER(channel) AS marketing_Channel, SUM(COALESCE(spend, 0)) AS spend, SUM(COALESCE(impressions, 0)) AS ad_impressions, SUM(COALESCE(clicks, 0)) AS ad_clicks, SUM(COALESCE(conversions, 0)) AS ad_conversions, SUM(COALESCE(conversion_value, 0)) AS ad_sales FROM public.tuco_kids_MARKETING_CONSOLIDATED GROUP BY 1, 2, 3 ) SELECT COALESCE(fi.Date, MC.date, SC.date) AS date, UPPER(COALESCE(fi.marketplace, MC.marketplace, RS.marketplace, SC.marketplace)) AS Marketplace, UPPER(COALESCE(fi.marketing_channel, MC.marketing_Channel, RS.marketing_channel, SC.marketing_channel)) AS Marketing_Channel, Total_Sales, TOTAL_SALES_EXCL_CANCL, SC.sessions, Total_Orders, Orders_EXCL_CANCL, New_Customer_Orders, New_Customer_Orders_EXCL_CANCL, Total_New_Customers, New_Customers_EXCL_CANCL, TOTAL_Unique_Customers, Unique_Customers_EXCL_CANCL, Repeat_Customers, Repeat_Customers_EXCL_CANCL, TOTAL_DISCOUNT, TOTAL_DISCOUNT_EXCL_CANCL, TOTAL_TAX, TAX_EXCL_CANCL, TOTAL_SHIPPING_PRICE, SHIPPING_PRICE_EXCL_CANCL, New_Customer_DISCOUNT, New_Customer_Discount_EXCL_CANCL, TOTAL_QUANTITY, QUANTITY_EXCL_CANCL, RS.TOTAL_RETURNED_QUANTITY AS Return_Quantity, RS.TOTAL_RETURN_AMOUNT AS Return_Value, Cancelled_Orders, Net_Orders, Delivered_Orders, Delivered_Revenue, Dispatched_Orders, Dispatched_Revenue, Realised_Orders, Realised_Revenue, spend AS marketing_spend, COD_Orders, Repeat_Customer_Revenue, MC.ad_conversions, MC.ad_impressions, MC.ad_clicks, MC.ad_sales FROM orders FI FULL OUTER JOIN spendd2c MC ON FI.Date = MC.date AND LOWER(FI.marketing_channel) = LOWER(MC.marketing_channel) AND LOWER(FI.Marketplace) = LOWER(MC.Marketplace) FULL OUTER JOIN returnsales RS ON RS.return_date = COALESCE(FI.date, MC.date) AND LOWER(RS.marketing_Channel) = LOWER(COALESCE(FI.marketing_Channel, MC.marketing_channel)) AND LOWER(RS.marketplace) = LOWER(COALESCE(FI.marketplace, MC.marketplace)) FULL OUTER JOIN SESSIONS SC ON COALESCE(FI.Date, MC.date, RS.return_date) = SC.Date AND LOWER(COALESCE(FI.Marketing_Channel, MC.marketing_channel, RS.marketing_Channel)) = LOWER(SC.Marketing_Channel) AND LOWER(COALESCE(FI.marketplace, MC.marketplace, RS.marketplace)) = LOWER(SC.Marketplace);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

